  function t(key){return (I18N[lang()]&&I18N[lang()][key])||I18N.en[key]||key;}
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
  function applyLanguage(){document.documentElement.lang=lang();$('#dateLabel').textContent=new Intl.DateTimeFormat(lang(),{weekday:'short',month:'short',day:'numeric'}).format(new Date()).toUpperCase();$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(t(key))el.textContent=t(key);});$$('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));renderTableLegendText();renderLesson(currentLesson);updateProgressText();updateStatsUI();}
  function renderTableLegendText(){const all=$('#categoryFilter')?.options;if(!all)return;[...all].forEach(o=>{if(o.dataset.i18n)o.textContent=t(o.dataset.i18n);});}
  function applySettings(){const root=document.documentElement;let theme=state.settings.theme;if(theme==='system')theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';root.dataset.theme=theme;root.dataset.accent=state.settings.accent;root.dataset.font=state.settings.font;root.dataset.compact=String(!!state.settings.compact);root.dataset.motion=state.settings.reducedMotion?'reduced':'normal';$('#themeSelect').value=state.settings.theme;$('#fontScale').value=state.settings.font;$('#compactToggle').checked=!!state.settings.compact;$('#motionToggle').checked=!!state.settings.reducedMotion;$('#languageSelect').value=lang();$$('.swatch').forEach(b=>b.classList.toggle('active',b.dataset.accent===state.settings.accent));}
  function navigate(view){if(!$('#view-'+view))return;currentView=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('[data-view-link]').forEach(b=>b.classList.toggle('active',b.dataset.viewLink===view));if(view==='groups'&&!currentGroupQuestion)nextGroupQuestion();if(view==='polarity'&&!currentMolecule)nextMolecule();if(view==='syllabus')renderLesson(currentLesson);window.scrollTo({top:0,behavior:state.settings.reducedMotion?'auto':'smooth'});}
  $$('[data-view]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.view)));
  $$('[data-view-link]').forEach(button=>button.addEventListener('click',e=>{e.preventDefault();navigate(button.dataset.viewLink);}));
  $('#openSettings').addEventListener('click',()=>$('#settingsDialog').showModal());$('#mobileSettings').addEventListener('click',()=>$('#settingsDialog').showModal());
  $('#progressButton').addEventListener('click',()=>{navigate('groups');toast(`${state.stats.groupCorrect} / ${state.stats.groupAttempts} ${t('answerCount')}`);});
  $('#themeSelect').addEventListener('change',e=>{state.settings.theme=e.target.value;applySettings();saveState();});
  $('#fontScale').addEventListener('change',e=>{state.settings.font=e.target.value;applySettings();saveState();});
  $('#compactToggle').addEventListener('change',e=>{state.settings.compact=e.target.checked;applySettings();saveState();});
  $('#motionToggle').addEventListener('change',e=>{state.settings.reducedMotion=e.target.checked;applySettings();saveState();});
  $('#languageSelect').addEventListener('change',e=>{state.settings.language=e.target.value;applySettings();applyLanguage();saveState();});
  $$('.swatch').forEach(b=>b.addEventListener('click',()=>{state.settings.accent=b.dataset.accent;applySettings();saveState();}));
  $('#clearProgress').addEventListener('click',()=>{if(confirm(t('progressResetConfirm'))){state.stats=defaultState().stats;state.lessons={};saveState();updateStatsUI();renderLesson(currentLesson);updateProgressText();toast(t('progressCleared'));}});
  $('#dateLabel').textContent=new Intl.DateTimeFormat(lang(),{weekday:'short',month:'short',day:'numeric'}).format(new Date()).toUpperCase();

  // ---- Periodic table ----
  const ELEMENTS = (window.ELEMENTS||[]).map(e=>({...e}));
  const byNumber = new Map(ELEMENTS.map(e=>[e.number,e]));
  function tablePosition(e){if(e.number>=58&&e.number<=71)return {row:8,col:e.number-54};if(e.number>=90&&e.number<=103)return {row:9,col:e.number-86};return {row:e.period,col:e.group};}
  function valence(e){if(e.group===18)return e.symbol==='He'?'2':'8';if(e.group===1||e.group===2)return String(e.group);if(e.group>=13&&e.group<=17)return String(e.group-10);return lang()==='id'?'Bervariasi':'Variable';}
  function classLabel(kind){return kind==='metal'?t('metal'):kind==='metalloid'?t('metalloid'):t('nonmetal');}
  function renderPeriodicTable(){const grid=$('#periodicGrid');grid.innerHTML='';ELEMENTS.forEach(e=>{const pos=tablePosition(e);const cell=document.createElement('button');cell.type='button';cell.className=`element-cell ${e.kind}${e.number>=58&&e.number<=71||e.number>=90&&e.number<=103?' fblock':''}`;cell.style.gridRow=pos.row;cell.style.gridColumn=pos.col;cell.dataset.number=e.number;cell.dataset.kind=e.kind;cell.setAttribute('aria-label',`${e.name}, atomic number ${e.number}, group ${e.group}, period ${e.period}`);cell.innerHTML=`<span class="cell-number">${e.number}</span><strong class="cell-symbol">${e.symbol}</strong><span class="cell-mass">${e.atomicMass}</span><span class="cell-name">${e.name}</span>`;cell.addEventListener('mouseenter',()=>{if(pinnedElementNumber===null)showElement(e,false);});cell.addEventListener('focus',()=>{if(pinnedElementNumber===null)showElement(e,false);});cell.addEventListener('click',()=>{pinnedElementNumber=e.number;showElement(e,true);});cell.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();showElement(e,true);}});grid.appendChild(cell);});applyTableFilters();}
  function showElement(e,selected=true){currentElement=e;$('#inspectorEmpty').classList.add('hidden');$('#inspectorDetail').classList.remove('hidden');$('#detailNumber').textContent=String(e.number).padStart(2,'0');$('#detailPhase').textContent=e.phase.toUpperCase();$('#detailSymbol').textContent=e.symbol;$('#detailName').textContent=e.name;$('#detailCategory').textContent=classLabel(e.kind);$('#detailMass').textContent=e.atomicMass;$('#detailAtomicNumber').textContent=e.number;$('#detailValence').textContent=valence(e);$('#detailGroup').textContent=(e.number>=58&&e.number<=71)||(e.number>=90&&e.number<=103)?'f-block':(GROUP_LABEL[e.group]?`${GROUP_LABEL[e.group]} · ${e.group}`:`${e.group}`);$('#detailPeriod').textContent=e.period;$('#detailKindPill').textContent=classLabel(e.kind).toUpperCase();$$('.element-cell').forEach(c=>c.classList.toggle('selected',selected&&Number(c.dataset.number)===e.number));}
  function applyTableFilters(){const q=$('#elementSearch').value.trim().toLowerCase();const kind=$('#categoryFilter').value;let shown=0;$$('.element-cell').forEach(cell=>{const e=byNumber.get(Number(cell.dataset.number));const matchesKind=kind==='all'||e.kind===kind;const matchesQuery=!q||`${e.name} ${e.symbol} ${e.number}`.toLowerCase().includes(q);const match=matchesKind&&matchesQuery;cell.classList.toggle('dimmed',!match);cell.classList.toggle('search-match',!!q&&match);if(match)shown++;});$('#tableCount').textContent=`${shown} / 118`;if(q){const match=ELEMENTS.find(e=>e.symbol.toLowerCase()===q||e.name.toLowerCase()===q||String(e.number)===q);if(match)showElement(match,false);}if(!shown){$('#inspectorEmpty').classList.remove('hidden');$('#inspectorDetail').classList.add('hidden');$('#inspectorEmpty h3').textContent=t('noSearchResults');$('#inspectorEmpty p').textContent='';}}
  $('#elementSearch').addEventListener('input',()=>{pinnedElementNumber=null;applyTableFilters();});$('#categoryFilter').addEventListener('change',applyTableFilters);$('#resetTable').addEventListener('click',()=>{pinnedElementNumber=null;$('#elementSearch').value='';$('#categoryFilter').value='all';$$('.element-cell').forEach(c=>c.classList.remove('selected'));applyTableFilters();$('#inspectorEmpty h3').textContent=t('pickElement');$('#inspectorEmpty p').textContent=t('pickElementHelp');$('#inspectorEmpty').classList.remove('hidden');$('#inspectorDetail').classList.add('hidden');currentElement=null;});
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#settingsDialog').open){e.preventDefault();navigate('periodic');$('#elementSearch').focus();}});
  function focusElementOnTable(number){const e=byNumber.get(number);if(!e)return;pinnedElementNumber=number;navigate('periodic');$('#elementSearch').value='';$('#categoryFilter').value='all';applyTableFilters();showElement(e,true);const cell=$(`.element-cell[data-number="${number}"]`);cell?.scrollIntoView({behavior:state.settings.reducedMotion?'auto':'smooth',block:'nearest',inline:'center'});}

  // ---- Endless A-group challenge ----
  const mainGroupElements=ELEMENTS.filter(e=>GROUPS.includes(e.group));
  function shuffled(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
  function nextGroupQuestion(){let pool=mainGroupElements.filter(e=>e.number!==lastGroupNumber);if(!pool.length)pool=mainGroupElements;currentGroupQuestion=pool[Math.floor(Math.random()*pool.length)];lastGroupNumber=currentGroupQuestion.number;groupQuestionNo++;$('#groupQNumber').textContent=currentGroupQuestion.number;$('#groupQSymbol').textContent=currentGroupQuestion.symbol;$('#groupQName').textContent=currentGroupQuestion.name;$('#groupQuestionCounter').textContent=`QUESTION ${String(groupQuestionNo).padStart(2,'0')}`;$('#groupFeedback').classList.add('hidden');$('#nextGroupQuestion').disabled=true;$$('.answer-option').forEach(b=>{b.disabled=false;b.classList.remove('correct','wrong');});}
  function answerGroup(group){if(!currentGroupQuestion||$('#nextGroupQuestion').disabled===false)return;const right=Number(group)===currentGroupQuestion.group;state.stats.groupAttempts++;if(right){state.stats.groupCorrect++;state.stats.groupStreak++;state.stats.groupBestStreak=Math.max(state.stats.groupBestStreak,state.stats.groupStreak);}else state.stats.groupStreak=0;saveState();$$('.answer-option').forEach(b=>{b.disabled=true;if(Number(b.dataset.group)===currentGroupQuestion.group)b.classList.add('correct');if(Number(b.dataset.group)===Number(group)&&!right)b.classList.add('wrong');});const feedback=$('#groupFeedback');feedback.classList.remove('hidden','is-wrong');if(!right)feedback.classList.add('is-wrong');$('#groupFeedbackIcon').textContent=right?'✓':'!';$('#groupFeedbackTitle').textContent=right?t('answerCorrect'):t('answerWrong');const groupLabel=GROUP_LABEL[currentGroupQuestion.group];const family=GROUP_NAME[currentGroupQuestion.group][lang()]||GROUP_NAME[currentGroupQuestion.group].en;$('#groupFeedbackText').textContent=currentGroupQuestion.symbol==='H'?(lang()==='id'?'Hidrogen ditempatkan di IA (golongan 1) karena memiliki satu elektron valensi. Namun, hidrogen adalah nonlogam dan bukan logam alkali.':lang()==='es'?'Hydrogen is placed in IA (group 1) because it has one valence electron, but it is a nonmetal—not an alkali metal.':lang()==='fr'?'L’hydrogène est placé en IA (groupe 1) car il possède un électron de valence, mais c’est un non-métal, pas un métal alcalin.':'Hydrogen is placed in IA (group 1) because it has one valence electron, but it is a nonmetal—not an alkali metal.'):`${currentGroupQuestion.name} (${currentGroupQuestion.symbol}) belongs to ${groupLabel} — ${family}.`;$('#groupAnswerLocation').innerHTML=`<button type="button" class="inline-location">${currentGroupQuestion.symbol} · ${t('showOnTable')}</button> <span>Period ${currentGroupQuestion.period} · Group ${currentGroupQuestion.group}</span>`;$('.inline-location',$('#groupAnswerLocation')).addEventListener('click',()=>focusElementOnTable(currentGroupQuestion.number));$('#nextGroupQuestion').disabled=false;updateStatsUI();}
  $$('.answer-option').forEach(b=>b.addEventListener('click',()=>answerGroup(b.dataset.group)));$('#nextGroupQuestion').addEventListener('click',nextGroupQuestion);$('#resetGroupStats').addEventListener('click',()=>{state.stats.groupCorrect=0;state.stats.groupAttempts=0;state.stats.groupStreak=0;state.stats.groupBestStreak=0;saveState();updateStatsUI();nextGroupQuestion();});
  function updateStatsUI(){const s=state.stats;$('#groupCorrect').textContent=s.groupCorrect;$('#groupStreak').innerHTML=`${s.groupStreak} <em>✦</em>`;$('#groupAccuracy').textContent=s.groupAttempts?`${Math.round(s.groupCorrect/s.groupAttempts*100)}%`:'—';$('#groupAttempts').textContent=s.groupAttempts;$('#groupProgressBar').style.width=`${s.groupAttempts?Math.round(s.groupCorrect/s.groupAttempts*100):0}%`;$('#topStreak').textContent=s.groupStreak;$('#sidebarProgress').textContent=`${s.groupAttempts} ${t('answerCount')}`;$('#polarityScore').innerHTML=`${s.polarityCorrect} <small>/ ${s.polarityAttempts}</small>`;$('#polarityProgressBar').style.width=`${s.polarityAttempts?100*s.polarityCorrect/s.polarityAttempts:0}%`;}

  // ---- Molecular polarity cards ----
  const MOLECULES=[
    {formula:'H₂O',name:'Water',shape:'Bent · AX₂E₂',polar:true,explain:'Each O–H bond is polar because oxygen is more electronegative than hydrogen. The molecule is bent, so the two bond-dipole vectors do not oppose each other perfectly. Their vector sum points toward oxygen, giving water a net dipole.',takeaway:'Bent geometry + polar O–H bonds → the dipoles do not cancel.'},
    {formula:'CO₂',name:'Carbon dioxide',shape:'Linear · AX₂',polar:false,explain:'Each C=O bond is polar, but the molecule is linear and symmetrical. The two equal bond dipoles point in opposite directions, so they cancel exactly in the ideal molecule.',takeaway:'Polar bonds do not guarantee a polar molecule: symmetry can cancel the dipoles.'},
    {formula:'NH₃',name:'Ammonia',shape:'Trigonal pyramidal · AX₃E',polar:true,explain:'Nitrogen has one lone pair and three N–H bonds. The trigonal-pyramidal shape is not symmetrical enough for the bond dipoles to cancel. The net dipole points broadly toward nitrogen and its lone-pair region.',takeaway:'A lone pair changes the molecular shape and can prevent dipole cancellation.'},
    {formula:'BF₃',name:'Boron trifluoride',shape:'Trigonal planar · AX₃',polar:false,explain:'The B–F bonds are strongly polar, but three identical bonds are arranged symmetrically in one plane at about 120°. Their vectors balance, so the molecule has no net dipole moment.',takeaway:'Three identical bond dipoles arranged symmetrically cancel.'},
    {formula:'CH₄',name:'Methane',shape:'Tetrahedral · AX₄',polar:false,explain:'The C–H bond polarity is small, and the four identical bonds point toward the corners of a regular tetrahedron. Their vector contributions cancel by symmetry.',takeaway:'A regular tetrahedral arrangement with four identical substituents is nonpolar.'},
    {formula:'HCl',name:'Hydrogen chloride',shape:'Linear diatomic',polar:true,explain:'A diatomic molecule made of two different atoms has one bond dipole. There is no second bond dipole to cancel it. Chlorine attracts the shared electrons more strongly, so HCl is polar.',takeaway:'A heteronuclear diatomic molecule is polar when its bond is polar.'},
    {formula:'Cl₂',name:'Chlorine',shape:'Linear diatomic',polar:false,explain:'Both atoms are chlorine, so they have the same electronegativity. The bonding electrons are shared equally and there is no permanent bond dipole.',takeaway:'Identical atoms → no electronegativity difference → no bond dipole.'},
    {formula:'SO₂',name:'Sulfur dioxide',shape:'Bent · AX₂E',polar:true,explain:'The S–O bonds are polar. Sulfur dioxide is bent because the central sulfur has a lone pair in the simple VSEPR description. The bond-dipole vectors therefore do not cancel.',takeaway:'Bent geometry creates a net dipole when the bonds are polar.'},
    {formula:'CCl₄',name:'Carbon tetrachloride',shape:'Tetrahedral · AX₄',polar:false,explain:'Every C–Cl bond is polar, but the four identical C–Cl bonds occupy the corners of a symmetrical tetrahedron. The dipole vectors cancel in three dimensions.',takeaway:'A symmetrical tetrahedron with four identical outer atoms is nonpolar.'},
    {formula:'CH₃Cl',name:'Chloromethane',shape:'Tetrahedral · AX₄',polar:true,explain:'The tetrahedral arrangement is not symmetrical because one chlorine replaces one of the four hydrogens. The strong C–Cl dipole is not balanced by the three C–H bonds, so a net dipole remains.',takeaway:'A tetrahedral shape is not automatically nonpolar; the outer atoms must also match.'},
    {formula:'HCN',name:'Hydrogen cyanide',shape:'Linear',polar:true,explain:'HCN is linear, but its two ends are different: hydrogen and nitrogen. The bond dipoles do not balance; electron density is drawn toward the nitrogen end, leaving a net molecular dipole.',takeaway:'Linear molecules can be polar when the two ends are different.'},
    {formula:'CS₂',name:'Carbon disulfide',shape:'Linear · AX₂',polar:false,explain:'The molecule is linear and symmetrical, with sulfur atoms at both ends. The two C–S bond-dipole contributions cancel. The C–S bonds are also only weakly polar.',takeaway:'Identical terminal atoms in a linear molecule give dipole cancellation.'},
    {formula:'PCl₃',name:'Phosphorus trichloride',shape:'Trigonal pyramidal · AX₃E',polar:true,explain:'Phosphorus has three P–Cl bonds and one lone pair. Its trigonal-pyramidal geometry means the three polar P–Cl bond dipoles do not cancel, leaving a net dipole.',takeaway:'Trigonal-pyramidal molecules with polar bonds are usually polar.'},
    {formula:'SF₆',name:'Sulfur hexafluoride',shape:'Octahedral · AX₆',polar:false,explain:'The six S–F bonds are polar, but they are arranged symmetrically at the vertices of an octahedron. Opposite bond-dipole contributions cancel in pairs.',takeaway:'Octahedral AX₆ with six identical ligands is symmetrical and nonpolar.'},
    {formula:'PF₅',name:'Phosphorus pentafluoride',shape:'Trigonal bipyramidal · AX₅',polar:false,explain:'PF₅ has a trigonal-bipyramidal shape. With five identical fluorine atoms, the three equatorial bond dipoles cancel each other and the two axial bond dipoles cancel along the same axis.',takeaway:'Identical ligands in an ideal trigonal-bipyramidal structure can balance.'},
    {formula:'SF₄',name:'Sulfur tetrafluoride',shape:'Seesaw · AX₄E',polar:true,explain:'One lone pair occupies an equatorial position in the trigonal-bipyramidal electron arrangement, giving SF₄ a seesaw molecular shape. The S–F bond dipoles are not symmetrically balanced.',takeaway:'The seesaw shape is asymmetrical, so polar bonds leave a net dipole.'},
    {formula:'XeF₂',name:'Xenon difluoride',shape:'Linear · AX₂E₃',polar:false,explain:'Three lone pairs occupy the equatorial positions of a trigonal-bipyramidal electron arrangement. The two Xe–F bonds remain opposite each other, so their equal dipoles cancel.',takeaway:'AX₂E₃ is linear; identical terminal atoms cancel the bond dipoles.'},
    {formula:'XeF₄',name:'Xenon tetrafluoride',shape:'Square planar · AX₄E₂',polar:false,explain:'Two lone pairs sit opposite each other in an octahedral electron arrangement. The four Xe–F bonds form a square plane and their dipole vectors cancel in opposing pairs.',takeaway:'Square-planar AX₄E₂ with four identical ligands is nonpolar.'},
    {formula:'BrF₅',name:'Bromine pentafluoride',shape:'Square pyramidal · AX₅E',polar:true,explain:'BrF₅ has an octahedral electron-domain arrangement with one lone pair, producing a square-pyramidal molecular shape. The bond-dipole vectors do not cancel completely.',takeaway:'Square-pyramidal geometry is asymmetrical and generally gives a net dipole.'},
    {formula:'BeCl₂',name:'Beryllium chloride',shape:'Linear · AX₂',polar:false,explain:'In the isolated molecular form, BeCl₂ is linear. The two equal Be–Cl bond dipoles point in opposite directions and cancel.',takeaway:'Linear and symmetrical with identical terminal atoms → nonpolar.'},
    {formula:'O₃',name:'Ozone',shape:'Bent · AX₂E',polar:true,explain:'Ozone has a bent structure around the central oxygen. Its O–O bonds are not equivalent in the simple resonance-bond picture, and the bent geometry gives a net dipole.',takeaway:'A bent triatomic molecule can have a net dipole even when all atoms are the same element.'},
    {formula:'NO₂',name:'Nitrogen dioxide',shape:'Bent · AX₂',polar:true,explain:'NO₂ is bent rather than linear, so the two N–O bond-dipole contributions do not cancel. It is also an odd-electron molecule, so simple AXₙEₘ counting needs care.',takeaway:'Its bent geometry leaves a resultant dipole; the radical electron makes the simple VSEPR label less complete.'},
    {formula:'CH₂O',name:'Formaldehyde',shape:'Trigonal planar around C',polar:true,explain:'The C=O bond is strongly polar, and the two C–H bonds do not cancel that contribution. The trigonal-planar arrangement therefore has a net dipole directed mainly toward oxygen.',takeaway:'A strong polar bond in an unsymmetrical arrangement usually dominates the vector sum.'},
    {formula:'C₂H₂',name:'Ethyne (acetylene)',shape:'Linear',polar:false,explain:'Ethyne is linear and symmetrical, H–C≡C–H. The two ends are identical, so the molecule has no net dipole moment.',takeaway:'A symmetrical linear molecule with identical ends is nonpolar.'},
    {formula:'C₂H₄',name:'Ethene (ethylene)',shape:'Planar around each C',polar:false,explain:'Ethene is planar and symmetrical. Its C–H and C=C bond contributions balance across the molecule, so it has no permanent net dipole in the ideal structure.',takeaway:'Overall molecular symmetry can cancel local bond-dipole contributions.'},
    {formula:'CH₃OH',name:'Methanol',shape:'Tetrahedral C; bent O',polar:true,explain:'Methanol contains a polar C–O bond and a polar O–H bond. The geometry around oxygen is bent, and the molecule is not symmetrical, leaving a net dipole.',takeaway:'Multiple polar bonds in an unsymmetrical molecule generally produce a net dipole.'},
    {formula:'N₂',name:'Nitrogen',shape:'Linear diatomic',polar:false,explain:'The two atoms are identical nitrogen atoms. The N≡N bond has no electronegativity difference and therefore no permanent bond dipole.',takeaway:'Homonuclear diatomic molecules are nonpolar.'},
    {formula:'CH₂Cl₂',name:'Dichloromethane',shape:'Tetrahedral · AX₄',polar:true,explain:'The tetrahedral molecule has two chlorine and two hydrogen atoms around carbon. Because the substituents are not all identical, the C–Cl bond dipoles do not cancel completely.',takeaway:'Two pairs of different substituents in a tetrahedron can still leave a net dipole.'},
    {formula:'H₂S',name:'Hydrogen sulfide',shape:'Bent · AX₂E₂',polar:true,explain:'H₂S is bent, so its two S–H bond-dipole contributions do not cancel exactly. The bonds are less polar than O–H bonds, but the molecule still has a small net dipole.',takeaway:'Bent geometry can produce a net dipole even when individual bonds are only weakly polar.'},
    {formula:'ClF₃',name:'Chlorine trifluoride',shape:'T-shaped · AX₃E₂',polar:true,explain:'Two equatorial lone pairs in a trigonal-bipyramidal electron arrangement give ClF₃ a T-shaped molecular geometry. The three Cl–F bond dipoles are not balanced, so the molecule is polar.',takeaway:'T-shaped AX₃E₂ is asymmetrical and polar when its bonds are polar.'}
  ];
  const MOLECULE_ID={
    'H₂O':['Setiap ikatan O–H bersifat polar karena oksigen lebih elektronegatif daripada hidrogen. Bentuk molekulnya bengkok, sehingga dua vektor dipol ikatan tidak saling berlawanan secara sempurna. Resultannya mengarah ke oksigen dan menghasilkan dipol total.','Geometri bengkok + ikatan O–H polar → dipol tidak saling meniadakan.'],
    'CO₂':['Setiap ikatan C=O bersifat polar, tetapi molekulnya linear dan simetris. Dua dipol ikatan yang sama besar mengarah ke arah berlawanan sehingga saling meniadakan.','Ikatan polar tidak selalu membuat molekul polar: simetri dapat meniadakan dipol.'],
    'NH₃':['Nitrogen memiliki satu pasangan bebas dan tiga ikatan N–H. Bentuk trigonal piramida tidak cukup simetris untuk meniadakan seluruh dipol ikatan. Resultan dipol mengarah secara umum ke nitrogen.','Pasangan bebas mengubah bentuk molekul dan dapat mencegah pembatalan dipol.'],
    'BF₃':['Ikatan B–F sangat polar, tetapi tiga ikatan identik tersusun simetris pada satu bidang dengan sudut sekitar 120°. Vektor dipolnya seimbang sehingga tidak ada dipol total.','Tiga dipol ikatan identik yang tersusun simetris dapat saling meniadakan.'],
    'CH₄':['Kepolaran ikatan C–H kecil, dan empat ikatan identik mengarah ke sudut tetrahedron beraturan. Kontribusi vektornya saling meniadakan karena simetri.','Susunan tetrahedral beraturan dengan empat substituen identik bersifat nonpolar.'],
    'HCl':['Molekul diatomik ini memiliki satu dipol ikatan. Tidak ada dipol kedua yang dapat meniadakannya. Klorin menarik elektron lebih kuat, sehingga HCl bersifat polar.','Molekul diatomik heteronuklir dengan ikatan polar memiliki dipol total.'],
    'Cl₂':['Kedua atomnya adalah klorin, sehingga keelektronegatifannya sama. Elektron ikatan dibagi secara setara dan tidak terbentuk dipol ikatan permanen.','Atom identik → tidak ada perbedaan keelektronegatifan → tidak ada dipol ikatan.'],
    'SO₂':['Ikatan S–O bersifat polar. Sulfur dioksida berbentuk bengkok karena atom sulfur pusat memiliki pasangan bebas dalam gambaran VSEPR sederhana. Karena itu, vektor dipol ikatan tidak saling meniadakan.','Geometri bengkok menghasilkan dipol total ketika ikatannya polar.'],
    'CCl₄':['Setiap ikatan C–Cl bersifat polar, tetapi empat ikatan identik menempati sudut tetrahedron yang simetris. Vektor dipol saling meniadakan dalam tiga dimensi.','Tetrahedron simetris dengan empat atom luar identik bersifat nonpolar.'],
    'CH₃Cl':['Susunannya tetrahedral, tetapi tidak simetris karena satu klorin menggantikan satu dari empat hidrogen. Dipol C–Cl yang kuat tidak diimbangi oleh tiga ikatan C–H, sehingga tersisa dipol total.','Bentuk tetrahedral tidak otomatis nonpolar; atom-atom luarnya juga harus identik.'],
    'HCN':['HCN berbentuk linear, tetapi kedua ujungnya berbeda: hidrogen dan nitrogen. Dipol ikatannya tidak seimbang; kerapatan elektron tertarik ke ujung nitrogen sehingga muncul dipol molekul.','Molekul linear dapat bersifat polar jika kedua ujungnya berbeda.'],
    'CS₂':['Molekul ini linear dan simetris, dengan atom sulfur pada kedua ujung. Kontribusi dipol ikatan C–S saling meniadakan. Ikatan C–S juga hanya sedikit polar.','Atom terminal identik pada molekul linear menghasilkan pembatalan dipol.'],
    'PCl₃':['Fosfor memiliki tiga ikatan P–Cl dan satu pasangan bebas. Geometri trigonal piramida membuat tiga dipol ikatan P–Cl tidak saling meniadakan, sehingga tersisa dipol total.','Molekul trigonal piramida dengan ikatan polar umumnya bersifat polar.'],
    'SF₆':['Enam ikatan S–F bersifat polar, tetapi tersusun simetris pada titik-titik sudut oktahedron. Kontribusi dipol dari arah yang berlawanan saling meniadakan berpasangan.','AX₆ oktahedral dengan enam ligan identik bersifat simetris dan nonpolar.'],
    'PF₅':['PF₅ berbentuk trigonal bipiramida. Dengan lima atom fluor identik, tiga dipol ikatan ekuatorial saling meniadakan dan dua dipol aksial saling meniadakan sepanjang sumbu yang sama.','Ligan identik pada struktur trigonal bipiramida ideal dapat menghasilkan keseimbangan dipol.'],
    'SF₄':['Satu pasangan bebas menempati posisi ekuatorial dalam susunan domain elektron trigonal bipiramida, sehingga SF₄ berbentuk jungkat-jungkit. Dipol ikatan S–F tidak tersusun simetris.','Bentuk jungkat-jungkit tidak simetris, sehingga ikatan polar menyisakan dipol total.'],
    'XeF₂':['Tiga pasangan bebas menempati posisi ekuatorial pada susunan domain elektron trigonal bipiramida. Dua ikatan Xe–F tetap saling berlawanan, sehingga dipolnya sama besar dan saling meniadakan.','AX₂E₃ berbentuk linear; atom terminal identik meniadakan dipol ikatan.'],
    'XeF₄':['Dua pasangan bebas berada pada posisi berlawanan dalam susunan domain elektron oktahedral. Empat ikatan Xe–F membentuk bidang persegi, dan vektor dipolnya saling meniadakan berpasangan.','AX₄E₂ planar persegi dengan empat ligan identik bersifat nonpolar.'],
    'BrF₅':['BrF₅ memiliki susunan domain elektron oktahedral dengan satu pasangan bebas, sehingga bentuk molekulnya piramida segi empat. Vektor dipol ikatan tidak saling meniadakan sepenuhnya.','Geometri piramida segi empat tidak simetris dan umumnya menghasilkan dipol total.'],
    'BeCl₂':['Dalam bentuk molekul terisolasi, BeCl₂ bersifat linear. Dua dipol ikatan Be–Cl yang sama besar mengarah berlawanan dan saling meniadakan.','Linear dan simetris dengan atom terminal identik → nonpolar.'],
    'O₃':['Ozon memiliki struktur bengkok di sekitar oksigen pusat. Ikatan O–O tidak ekuivalen dalam gambaran ikatan resonansi sederhana, dan geometri bengkok menghasilkan dipol total.','Molekul triatomik bengkok dapat memiliki dipol total meskipun semua atomnya dari unsur yang sama.'],
    'NO₂':['NO₂ berbentuk bengkok, bukan linear, sehingga dua kontribusi dipol N–O tidak saling meniadakan. NO₂ juga merupakan molekul ber-elektron ganjil, jadi penghitungan AXₙEₘ sederhana perlu digunakan dengan hati-hati.','Geometri bengkok menyisakan dipol resultan; elektron radikal membuat model VSEPR sederhana kurang lengkap.'],
    'CH₂O':['Ikatan C=O sangat polar, sedangkan dua ikatan C–H tidak meniadakan kontribusi tersebut. Susunan trigonal planar menghasilkan dipol total yang terutama mengarah ke oksigen.','Ikatan polar kuat pada susunan tidak simetris biasanya mendominasi jumlah vektor dipol.'],
    'C₂H₂':['Etuna berbentuk linear dan simetris, H–C≡C–H. Kedua ujungnya identik, sehingga molekul tidak memiliki dipol total.','Molekul linear simetris dengan ujung identik bersifat nonpolar.'],
    'C₂H₄':['Etena berbentuk planar dan simetris. Kontribusi ikatan C–H dan C=C saling menyeimbangkan pada molekul ideal, sehingga tidak memiliki dipol total permanen.','Simetri molekul secara keseluruhan dapat meniadakan kontribusi dipol ikatan lokal.'],
    'CH₃OH':['Metanol memiliki ikatan C–O dan O–H yang polar. Geometri di sekitar oksigen bengkok dan molekulnya tidak simetris, sehingga tersisa dipol total.','Beberapa ikatan polar pada molekul tidak simetris umumnya menghasilkan dipol total.'],
    'N₂':['Kedua atomnya adalah nitrogen yang identik. Ikatan N≡N tidak memiliki perbedaan keelektronegatifan, sehingga tidak ada dipol ikatan permanen.','Molekul diatomik homonuklir bersifat nonpolar.'],
    'CH₂Cl₂':['Molekul tetrahedral ini memiliki dua atom klorin dan dua atom hidrogen di sekitar karbon. Karena substituennya tidak semuanya identik, dipol ikatan C–Cl tidak sepenuhnya saling meniadakan.','Dua pasang substituen berbeda dalam tetrahedron masih dapat menghasilkan dipol total.'],
    'H₂S':['H₂S berbentuk bengkok, sehingga kontribusi dua dipol ikatan S–H tidak saling meniadakan secara tepat. Ikatannya kurang polar dibanding O–H, tetapi molekulnya tetap memiliki dipol total kecil.','Geometri bengkok dapat menghasilkan dipol total meskipun ikatannya hanya sedikit polar.'],
    'ClF₃':['Dua pasangan bebas ekuatorial dalam susunan domain elektron trigonal bipiramida membuat ClF₃ berbentuk T. Tiga dipol ikatan Cl–F tidak seimbang, sehingga molekul bersifat polar.','AX₃E₂ berbentuk T tidak simetris dan polar jika ikatannya polar.']
  };
  function nextMolecule(){let idx=Math.floor(Math.random()*MOLECULES.length);if(MOLECULES.length>1&&idx===lastMoleculeIndex)idx=(idx+1)%MOLECULES.length;lastMoleculeIndex=idx;currentMolecule=MOLECULES[idx];polarityCardNo++;$('#moleculeFormula').textContent=currentMolecule.formula;$('#moleculeName').textContent=currentMolecule.name;$('#moleculeShape').textContent=currentMolecule.shape.toUpperCase();$('#polarityCounter').textContent=`CARD ${String(polarityCardNo).padStart(2,'0')}`;$('#polarityFeedback').classList.add('hidden');$('#nextMolecule').disabled=true;[$('#polarYes'),$('#polarNo')].forEach(b=>{b.disabled=false;b.classList.remove('correct','wrong');});}
  function answerPolarity(isPolar){if(!currentMolecule||!$('#nextMolecule').disabled)return;const correct=isPolar===currentMolecule.polar;state.stats.polarityAttempts++;if(correct)state.stats.polarityCorrect++;saveState();const chosen=isPolar?$('#polarYes'):$('#polarNo');const correctBtn=currentMolecule.polar?$('#polarYes'):$('#polarNo');$('#polarYes').disabled=true;$('#polarNo').disabled=true;correctBtn.classList.add('correct');if(!correct)chosen.classList.add('wrong');const feedback=$('#polarityFeedback');feedback.classList.remove('hidden','is-wrong');if(!correct)feedback.classList.add('is-wrong');$('#polarityFeedbackIcon').textContent=correct?'✓':'!';$('#polarityFeedbackTitle').textContent=correct?t('polarityRight'):t('polarityWrong');$('#polarityVerdict').textContent=currentMolecule.polar?t('polarMolecule'):t('nonpolarMolecule');$('#polarityStatus').textContent=correct?t('correctStatus'):t('reviewStatus');const translated=lang()==='id'?MOLECULE_ID[currentMolecule.formula]:null;$('#polarityExplanation').textContent=translated?translated[0]:currentMolecule.explain;$('#dipoleTakeaway').textContent=translated?translated[1]:currentMolecule.takeaway;$('#nextMolecule').disabled=false;updateStatsUI();}
  $('#polarYes').addEventListener('click',()=>answerPolarity(true));$('#polarNo').addEventListener('click',()=>answerPolarity(false));$('#nextMolecule').addEventListener('click',nextMolecule);

